    text += page.get_text()
doc.close()

lines = text.split('\n')
# Look for rice production data
for i, line in enumerate(lines):
    lower = line.lower()
    if any(term in lower for term in ['tonne', 'million', 'production', 'producer']):
        if any(country in lower for country in ['china', 'india', 'banglades', 'indonesia', 'vietnam', 'thailand']):
            start = max(0, i-2)
            end = min(len(lines), i+3)
            for j in range(start, end):
                print(f"{j}: {lines[j]}")
            print("---")
